async function load(){const [me,s,t]=await Promise.all([api('/api/me'),api('/api/dashboard'),api('/api/tenants')]);if(me.role==='worker'){localStorage.setItem('worker_token',token);localStorage.removeItem('negrosky_token');location.replace('/worker');return}currentMe=me;tenants=t;$('login').classList.add('hidden');$('dashboard').classList.remove('hidden');const title=document.querySelector('#dashboard header .eyebrow');if(title)title.textContent='NEGROSKY LOYALTY V3 · BUILD 055';$('identity').textContent=`${me.name} · ${me.username||me.email||me.role}`;const superAdmin=me.role==='super_admin';$('tenant-form').closest('.panel').classList.toggle('hidden',!superAdmin);document.querySelector('#user-role option[value="super_admin"]').hidden=!superAdmin;document.querySelector('[data-view="system"]').classList.toggle('hidden',!superAdmin);['businesses','branches','users','customers'].forEach(k=>$(k).textContent=s[k]);renderTenants();fillTenantSelects();await loadSystemUrls();if(tenants.some(x=>x.status==='active'))await tenantChanged()}
function opts(items,label='name'){return items.map(x=>`<option value="${x.id}">${x[label]}</option>`).join('')}
function renderTenants(){const html=tenants.length?tenants.map(t=>`<div class="tenant ${t.status==='trashed'?'trash-row':''}"><div><b>${t.name}</b><small>/${t.slug}</small></div><div>${t.status==='active'?`<a href="/b/${t.slug}" target="_blank">Abrir cliente</a><a href="/api/public/${t.slug}/qr.png" target="_blank">QR público</a><a href="/poster/${t.slug}" target="_blank">Cartel imprimible</a><button type="button" class="secondary mini-action" onclick="editTenant(${t.id})">Editar</button>${currentMe?.role==='super_admin'?`<button type="button" class="trash mini-action" onclick="trashTenant(${t.id})">Papelera</button>`:''}`:currentMe?.role==='super_admin'?`<button type="button" class="resume mini-action" onclick="restoreTenant(${t.id})">Restaurar</button>`:''}<span class="status">● ${ES.states[t.status]||ES.escape(t.status)}</span></div></div>`).join(''):'<div class="empty-state"><b>Primero crea un negocio</b><p>Luego podrás agregar sucursales, trabajadores y programas.</p></div>';$('tenant-list').innerHTML=html;$('business-list').innerHTML=html}
function fillTenantSelects(){const o=opts(tenants.filter(x=>x.status==='active'));const ids=['program-tenant','customer-tenant','branch-tenant','user-tenant','history-tenant','service-tenant','appointment-tenant','time-tenant','notification-tenant','branding-tenant','module-tenant','collab-tenant'];ids.forEach(id=>{const el=$(id);if(el)el.innerHTML=o});const active=$('active-tenant');if(active){active.innerHTML=o;if(!active.value&&tenants.some(x=>x.status==='active'))active.value=String(tenants.find(x=>x.status==='active').id)}}
async function compressCollaborationImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const image=new Image();image.onload=()=>{const max=1600,scale=Math.min(1,max/image.width,max/image.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);let quality=.82,data=canvas.toDataURL('image/jpeg',quality);while(data.length>1800000&&quality>.45){quality-=.08;data=canvas.toDataURL('image/jpeg',quality)}resolve(data)};image.onerror=reject;image.src=reader.result};reader.onerror=reject;reader.readAsDataURL(file)})}
async function loadCollaborations(){if(!currentMe||!$('collab-tenant'))return;const id=+$('collab-tenant').value||+$('active-tenant')?.value||tenants.find(x=>x.status==='active')?.id;if(!id)return;$('collab-tenant').value=String(id);try{const [contacts,rows]=await Promise.all([api(`/api/collaborations/contacts?tenant_id=${id}`),api(`/api/collaborations?tenant_id=${id}`)]);const partner=$('collab-partner');partner.innerHTML=contacts.length?contacts.map(x=>`<option value="${x.id}">${ES.escape(x.name)}${x.whatsapp?' · WhatsApp '+ES.escape(x.whatsapp):''}</option>`).join(''):'<option value="">No hay negocios disponibles</option>';const list=$('collab-list');list.innerHTML=rows.length?rows.map(x=>{const accepted=x.requester_status==='accepted'&&x.partner_status==='accepted',active=accepted&&Boolean(x.is_active),mine=+$('collab-tenant').value===x.requester_tenant_id,myStatus=mine?x.requester_status:x.partner_status,otherStatus=mine?x.partner_status:x.requester_status;return `<article class="collab-row"><div><b>${ES.escape(x.title)}</b><small>${ES.escape(x.requester_name)} ↔ ${ES.escape(x.partner_name)}</small>${x.message?`<p>${ES.escape(x.message)}</p>`:''}<small>Mi estado: ${myStatus} · Otro negocio: ${otherStatus} · Publicidad: ${x.ad_seconds||5}s${x.ends_at?' · Finaliza: '+ES.escape(x.ends_at.replace('T',' ')):''}</small>${x.image_url?`<img class="collab-row-image" src="${ES.escape(x.image_url)}" alt="Flyer">`:''}</div><div class="collab-actions">${myStatus==='pending'?`<button type="button" onclick="setCollaborationStatus(${x.id},'accepted')">Aceptar</button><button type="button" class="danger" onclick="setCollaborationStatus(${x.id},'rejected')">Rechazar</button>`:''}${accepted?`<button type="button" onclick="toggleCollaboration(${x.id},${!active})">${active?'Desactivar':'Activar'}</button>`:''}<button type="button" class="secondary" onclick="editCollaboration(${x.id})">Editar</button><button type="button" class="danger" onclick="deleteCollaboration(${x.id})">Eliminar</button><span class="${active?'module-on':'module-off'}">${active?'ACTIVA':accepted?'DESACTIVADA':myStatus==='rejected'?'RECHAZADA':'PENDIENTE'}</span></div></article>`}).join(''):'<p class="muted">Todavía no hay propuestas.</p>';const contact=await api(`/api/collaborations/contact?tenant_id=${id}`).catch(()=>null);if(contact){$('collab-whatsapp').value=contact.whatsapp||'';$('collab-visible').checked=!!contact.visible}}catch(e){if($('collab-list'))$('collab-list').innerHTML=`<p class="error">${ES.escape(e.message)}</p>`}}
