async function loadUserBranches(){if(!tenants.length)return;const id=$('user-tenant').value||tenants[0].id;branches=await api(`/api/branches?tenant_id=${id}`);$('user-branch').innerHTML=opts(branches)}
async function loadUsers(){
  const id=$('user-tenant').value||tenants.find(x=>x.status==='active')?.id;
  const path=currentMe?.role==='super_admin'?'/api/users':`/api/users?tenant_id=${id}`;
  const u=await api(path);
  $('user-list').innerHTML=u.length?`<table><tr><th>Nombre</th><th>Usuario/correo</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr>${u.map(x=>{
    const safeName=x.name.replaceAll("'",'');
    const restore=`<button class="resume mini-action" onclick="setUserStatus(${x.id},'active')">Restaurar acceso</button>`;
    const regular=`<button class="secondary mini-action" onclick="supportCode(${x.id},'${safeName}')">Código</button><button class="secondary mini-action" onclick="forcePassword(${x.id})">Forzar clave</button><button class="${x.status==='active'?'trash':'resume'} mini-action" onclick="setUserStatus(${x.id},'${x.status==='active'?'blocked':'active'}')">${x.status==='active'?'Bloquear':'Reactivar'}</button>${x.role==='worker'?`<button class="trash mini-action" onclick="deleteWorker(${x.id},'${safeName}')">Borrar trabajador</button>`:''}`;
    return `<tr><td>${x.name}</td><td><b>${x.username||'-'}</b><br><small>${x.email||'Correo opcional'}</small></td><td>${({worker:'Trabajador',branch_admin:'Administrador de sucursal',business_admin:'Dueño del negocio',super_admin:'Administrador general'})[x.role]||ES.escape(x.role)}</td><td>${x.status==='deleted'?'Borrado (historial conservado)':ES.states[x.status]||ES.escape(x.status)}${x.force_password_change?' · debe cambiar clave':''}</td><td>${x.status==='deleted'?restore:regular}</td></tr>`
  }).join('')}</table>`:'<p class="muted">Sin usuarios registrados.</p>';await loadWorkerAccessUsers(u)
}
const workerAccessLabels={validate_purchase:'Validar compras y fidelización',validate_raffle:'Validar rifas y boletas',validate_reward:'Entregar premios',time_sales:'Venta por tiempo',appointments:'Gestionar citas y reservas',notifications:'Enviar notificaciones'};
const workerAccessDays=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];
let workerAccessUsers=[];
function renderWorkerAccessControls(){const permissions=$('worker-access-permissions'),schedule=$('worker-access-schedule');if(permissions&&!permissions.children.length)permissions.innerHTML=Object.entries(workerAccessLabels).map(([key,label])=>`<label><input type="checkbox" data-worker-permission="${key}" checked> ${label}</label>`).join('');if(schedule&&!schedule.children.length)schedule.innerHTML=workerAccessDays.map((day,i)=>`<div class="worker-schedule-row"><label><input type="checkbox" data-worker-day="${i}" checked> ${day}</label><input type="time" data-worker-open="${i}" value="00:00"><span>a</span><input type="time" data-worker-close="${i}" value="23:59"></div>`).join('')}
async function loadWorkerAccess(){const id=+$('worker-access-user')?.value||0;if(!id)return;try{const a=await api(`/api/users/${id}/access`);document.querySelectorAll('[data-worker-permission]').forEach(x=>x.checked=a.permissions?.[x.dataset.workerPermission]!==false);(a.schedule||[]).forEach(x=>{const day=document.querySelector(`[data-worker-day="${x.weekday}"]`);const open=document.querySelector(`[data-worker-open="${x.weekday}"]`);const close=document.querySelector(`[data-worker-close="${x.weekday}"]`);if(day){day.checked=!!x.enabled;open.value=x.opens_at||'00:00';close.value=x.closes_at||'23:59'}});$('worker-access-message').textContent=''}catch(e){$('worker-access-message').textContent=e.message}}
function workerAccessPayload(){return {permissions:Object.fromEntries([...document.querySelectorAll('[data-worker-permission]')].map(x=>[x.dataset.workerPermission,x.checked])),schedule:[...Array(7)].map((_,i)=>({weekday:i,enabled:document.querySelector(`[data-worker-day="${i}"]`).checked,opens_at:document.querySelector(`[data-worker-open="${i}"]`).value,closes_at:document.querySelector(`[data-worker-close="${i}"]`).value}))}}
async function loadWorkerAccessUsers(users){const select=$('worker-access-user');if(!select)return;workerAccessUsers=(users||[]).filter(x=>x.role==='worker'&&x.status==='active');const old=select.value;select.innerHTML=workerAccessUsers.length?workerAccessUsers.map(x=>`<option value="${x.id}">${ES.escape(x.name)} · ${ES.escape(x.username||x.email||'')}</option>`).join(''):'<option value="">No hay trabajadores activos</option>';if(old&&workerAccessUsers.some(x=>String(x.id)===old))select.value=old;renderWorkerAccessControls();if(select.value)await loadWorkerAccess()}
renderWorkerAccessControls();$('worker-access-user')?.addEventListener('change',loadWorkerAccess);$('save-worker-access')?.addEventListener('click',async()=>{const id=+$('worker-access-user').value;if(!id)return;try{await api(`/api/users/${id}/access`,{method:'PUT',body:JSON.stringify(workerAccessPayload())});$('worker-access-message').textContent='Permisos y horario guardados para este trabajador.';showToast('Acceso del trabajador actualizado','success')}catch(e){$('worker-access-message').textContent=e.message;showToast(e.message,'error')}});$('worker-access-all')?.addEventListener('click',async()=>{const tenant=+$('user-tenant').value;if(!tenant)return;if(!confirm('¿Aplicar estos permisos y horarios a todos los trabajadores activos de este negocio?'))return;try{const r=await api('/api/worker-access/all',{method:'PUT',body:JSON.stringify({tenant_id:tenant,...workerAccessPayload()})});$('worker-access-message').textContent=`Configuración aplicada a ${r.updated} trabajador(es).`;showToast('Regla general aplicada','success')}catch(e){$('worker-access-message').textContent=e.message;showToast(e.message,'error')}});
async function loadPrograms(){if(!tenants.length)return;const id=$('program-tenant').value||tenants[0].id;[currentPrograms,currentTrash]=await Promise.all([api(`/api/loyalty-programs?tenant_id=${id}`),api(`/api/loyalty-programs/trash?tenant_id=${id}`)]);$('program-list').innerHTML=currentPrograms.length?currentPrograms.map(x=>{const availability=x.reward_display==='unlimited'?'Premios ilimitados':x.reward_display==='quantity'?`${x.rewards_remaining} de ${x.reward_stock} premios disponibles`:'Disponibilidad oculta al cliente';return `<div class="tenant campaign-row ${x.status==='active'?'':'campaign-paused'}"><div><b>${x.progress_emoji||'⭐'} ${x.name}</b><small>${x.target_purchases} compras · Premio: ${x.reward_name}</small><small>🎁 ${availability} · Ganados: ${x.rewards_issued}</small><span class="campaign-state ${x.status==='active'?'on':'off'}">${x.status==='active'?'● ACTIVA':'⏸ PAUSADA'}</span></div><div class="campaign-actions"><button type="button" class="secondary" onclick="editProgram(${x.id})">Editar</button><button type="button" class="${x.status==='active'?'danger':'resume'}" onclick="toggleProgram(${x.id},${x.status!=='active'})">${x.status==='active'?'Desactivar':'Reanudar'}</button><button type="button" class="trash" onclick="trashProgram(${x.id})">🗑️ Borrar</button></div></div>`}).join(''):'<p class="muted">Sin programas activos o pausados.</p>';$('trash-list').innerHTML=currentTrash.length?currentTrash.map(x=>`<div class="tenant trash-row"><div><b>${x.progress_emoji||'⭐'} ${x.name}</b><small>${x.target_purchases} compras · ${x.reward_name}</small><small>Progresos y ${x.rewards_issued} premio(s) conservados</small></div><button type="button" class="resume" onclick="restoreProgram(${x.id})">Restaurar campaña</button></div>`).join(''):'<p class="muted">La papelera está vacía.</p>'}
async function toggleProgram(id,active){const p=currentPrograms.find(x=>x.id===id);if(!p)return;if(!confirm(`${active?'Reanudar':'Desactivar'} la campaña ${p.name}?`))return;try{await api(`/api/loyalty-programs/${id}/status`,{method:'PUT',body:JSON.stringify({active})});$('program-message').textContent=active?'Campaña reanudada y visible para clientes':'Campaña pausada y oculta para clientes';await loadPrograms()}catch(e){$('program-message').textContent=e.message}}
async function trashProgram(id){const p=currentPrograms.find(x=>x.id===id);if(!p)return;if(!confirm(`¿Enviar “${p.name}” a la papelera? El progreso de los clientes NO se borrará.`))return;try{await api(`/api/loyalty-programs/${id}`,{method:'DELETE'});$('program-message').textContent='Campaña enviada a la papelera. Todo el progreso permanece guardado.';await loadPrograms()}catch(e){$('program-message').textContent=e.message}}
async function restoreProgram(id){const p=currentTrash.find(x=>x.id===id);if(!p)return;if(!confirm(`¿Restaurar y activar la campaña “${p.name}”?`))return;try{await api(`/api/loyalty-programs/${id}/restore`,{method:'PUT'});$('program-message').textContent='Campaña restaurada con el progreso anterior de cada cliente.';await loadPrograms()}catch(e){$('program-message').textContent=e.message}}
function editProgram(id){const p=currentPrograms.find(x=>x.id===id);if(!p)return;editingProgramId=id;$('program-name').value=p.name;$('program-target').value=p.target_purchases;$('program-reward').value=p.reward_name;$('program-emoji').value=p.progress_emoji||'⭐';$('program-reward-display').value=p.reward_display||'hidden';$('program-stock').value=p.reward_stock||100;$('program-title-mode').value=p.title_mode||'inherit';$('program-stamps-mode').value=p.stamps_mode||'inherit';$('program-progress-mode').value=p.progress_mode||'inherit';$('program-reward-mode').value=p.reward_mode||'inherit';$('program-button-mode').value=p.button_mode||'inherit';$('program-reward-display').onchange();const submit=$('program-form').querySelector('button[type="submit"],button:not([type])');submit.textContent='Guardar cambios';$('program-message').textContent='Editando campaña: '+p.name;document.querySelectorAll('.emoji-picker button').forEach(x=>x.classList.toggle('selected',x.textContent.trim()===$('program-emoji').value));$('program-name').focus()}
function customerWhatsAppLink(name,phone,business){const raw=String(phone||'').replace(/\D/g,'');const number=raw.startsWith('57')?raw:(raw.length===10?'57'+raw:raw);if(!number)return'#';const message=`Hola ${String(name||'').trim()}, te escribo de ${String(business||'tu negocio')}.`;return `https://wa.me/${number}?text=${encodeURIComponent(message)}`}
async function loadCustomers(){if(!tenants.length)return;const id=$('customer-tenant').value||tenants[0].id,q=$('customer-search').value.trim();const c=await api(`/api/customers?tenant_id=${id}${q?'&q='+encodeURIComponent(q):''}`);$('customer-detail').classList.add('hidden');$('customer-list').innerHTML=c.length?`<table><tr><th>Nombre</th><th>Celular</th><th>Sucursal/origen</th><th>Promociones</th><th>Registro</th><th>Contacto</th><th></th></tr>${c.map(x=>`<tr><td>${x.name}</td><td>${x.phone}</td><td>${x.origin_branch_name||'No indicada'}</td><td>${x.marketing_consent?'Sí':'No'}</td><td>${x.created_at.slice(0,10)}</td><td><a class="whatsapp-action" href="${customerWhatsAppLink(x.name,x.phone,x.business_name)}" target="_blank" rel="noopener noreferrer">💬 WhatsApp</a></td><td><button type="button" class="secondary mini-action" onclick="showCustomer(${x.id})">Ver ficha</button></td></tr>`).join('')}</table>`:`<div class="empty-state"><b>${q?'No encontramos coincidencias':'Sin clientes'}</b><p>${q?'Prueba con otro nombre o número.':'Abre la página pública del negocio para registrar el primero.'}</p></div>`}
async function loadHistory(){if(!tenants.length)return;const id=$('history-tenant').value||tenants[0].id;const h=await api(`/api/business/history?tenant_id=${id}`);const rows=[...h.purchases.map(x=>[x.created_at,'Compra',x.customer_name,x.program_name,x.branch_name,x.worker_name]),...h.rewards.map(x=>[x.claimed_at,'Premio',x.customer_name,x.reward_name,x.branch_name,x.worker_name])];$('business-history').innerHTML=rows.length?`<table><tr><th>Fecha</th><th>Tipo</th><th>Cliente</th><th>Detalle</th><th>Sucursal</th><th>Validó</th></tr>${rows.map(x=>`<tr>${x.map(v=>`<td>${v||'-'}</td>`).join('')}</tr>`).join('')}</table>`:'<p class="muted">Todavía no hay movimientos.</p>'}
$('history-tenant').onchange=loadHistory;document.addEventListener('click',e=>{const b=e.target.closest('.emoji-picker button');if(!b)return;e.preventDefault();$('program-emoji').value=b.textContent.trim();document.querySelectorAll('.emoji-picker button').forEach(x=>x.classList.toggle('selected',x===b));$('program-message').textContent='Emoji seleccionado: '+b.textContent.trim()});
$('branch-tenant').onchange=loadBranches;$('program-tenant').onchange=loadPrograms;$('customer-tenant').onchange=loadCustomers;$('user-tenant').onchange=async()=>{await loadUserBranches();await loadUsers()};$('refresh').onclick=load;$('logout').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST'})}catch(e){}localStorage.removeItem('negrosky_token');location.reload()};if(token)load().catch(()=>{localStorage.removeItem('negrosky_token');location.reload()});

const dayNames=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];
document.querySelector('.build-badge').textContent='BUILD 055 · CONTROL DE MÓDULOS · 8030';
const hourOptions=Array.from({length:288},(_,index)=>`${String(Math.floor(index/12)).padStart(2,'0')}:${String(index%12*5).padStart(2,'0')}`).concat('23:59');
const hourSelect=(kind,day,defaultValue)=>`<select class="day-${kind}" data-day="${day}" aria-label="${kind==='open'?'Apertura':'Cierre'} de ${dayNames[day]}">${hourOptions.map(time=>`<option value="${time}" ${time===defaultValue?'selected':''}>${ES.clock(time)}</option>`).join('')}</select>`;
function setHourValue(select,value){if(![...select.options].some(option=>option.value===value))select.add(new Option(ES.clock(value),value));select.value=value}
$('hours-grid').innerHTML=dayNames.map((name,day)=>`<div class="hour-row"><label><input class="day-enabled" data-day="${day}" type="checkbox" checked> ${name}</label>${hourSelect('open',day,'08:00')}<span>a</span>${hourSelect('close',day,'18:00')}</div>`).join('');
async function loadServiceBranches(){if(!tenants.length)return;const tenantId=+$('service-tenant').value||tenants[0].id;const rows=await api(`/api/branches?tenant_id=${tenantId}`);const selected=$('service-branch').value;$('service-branch').innerHTML='<option value="">Todo el negocio</option>'+opts(rows);if(rows.some(x=>String(x.id)===selected))$('service-branch').value=selected;$('copy-targets').innerHTML=opts(rows);await loadServiceSettings()}
async function loadServiceSettings(){if(!tenants.length)return;const tenantId=+$('service-tenant').value||tenants[0].id,branchId=$('service-branch').value;const query=`tenant_id=${tenantId}${branchId?'&branch_id='+branchId:''}`;try{const data=await api(`/api/service-settings?${query}`);$('schedule-mode-label').classList.toggle('hidden',!branchId);$('schedule-mode').value=data.schedule_mode;$('hours-grid').classList.toggle('inherited',data.schedule_mode==='inherit'&&!!branchId);$('manual-closed').checked=data.manual_closed;$('closed-message').value=data.closed_message;$('service-timezone').value=data.timezone;$('service-timezone').disabled=!!branchId;data.hours.forEach(h=>{document.querySelector(`.day-enabled[data-day="${h.weekday}"]`).checked=!!h.enabled;setHourValue(document.querySelector(`.day-open[data-day="${h.weekday}"]`),h.opens_at);setHourValue(document.querySelector(`.day-close[data-day="${h.weekday}"]`),h.closes_at)});const moduleValues=data.modules||{};document.querySelectorAll('[data-module]').forEach(x=>x.checked=!!moduleValues[x.dataset.module]);$('service-status-card').className='service-status-card '+(data.current_status.open?'open':'closed');$('service-status-card').innerHTML=data.current_status.open?'<b>🟢 Servicio disponible ahora</b><p>Los clientes pueden generar y validar operaciones.</p>':`<b>🔴 Fuera de servicio</b><p>${data.current_status.message}</p>`;Array.from($('copy-targets').options).forEach(o=>o.disabled=o.value===branchId)}catch(e){$('service-message').textContent=e.message}}
$('service-form').onsubmit=async e=>{e.preventDefault();const tenantId=+$('service-tenant').value,branchId=$('service-branch').value;const hours=dayNames.map((_,weekday)=>({weekday,enabled:document.querySelector(`.day-enabled[data-day="${weekday}"]`).checked,opens_at:document.querySelector(`.day-open[data-day="${weekday}"]`).value,closes_at:document.querySelector(`.day-close[data-day="${weekday}"]`).value}));const modules={};document.querySelectorAll('[data-module]').forEach(x=>modules[x.dataset.module]=x.checked);try{await api(`/api/service-settings?tenant_id=${tenantId}${branchId?'&branch_id='+branchId:''}`,{method:'PUT',body:JSON.stringify({manual_closed:$('manual-closed').checked,closed_message:$('closed-message').value,timezone:$('service-timezone').value,schedule_mode:branchId?$('schedule-mode').value:'custom',hours,modules})});$('service-message').textContent='Configuración guardada. El cambio ya está activo para los clientes.';await loadServiceSettings()}catch(e){$('service-message').textContent=e.message}};
$('copy-settings').onclick=async()=>{const tenantId=+$('service-tenant').value,source=$('service-branch').value,targets=Array.from($('copy-targets').selectedOptions).map(x=>+x.value).filter(id=>String(id)!==source);if(!targets.length){$('service-message').textContent='Selecciona al menos una sucursal de destino.';return}try{const r=await api('/api/service-settings/copy',{method:'POST',body:JSON.stringify({tenant_id:tenantId,source_branch_id:source?+source:null,target_branch_ids:targets})});$('service-message').textContent=`Configuración duplicada en ${r.branches_updated} sucursal(es).`;await loadServiceSettings()}catch(e){$('service-message').textContent=e.message}};
$('service-tenant').onchange=loadServiceBranches;$('service-branch').onchange=loadServiceSettings;$('schedule-mode').onchange=()=>{$('hours-grid').classList.toggle('inherited',$('schedule-mode').value==='inherit'&&!!$('service-branch').value)};

function slugify(value){return value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80)}
let tenantSlugTouched=false;
function updateTenantPreview(){const slug=slugify($('tenant-slug').value||$('tenant-name').value)||'mi-negocio';$('tenant-url-preview').textContent='La página quedará: '+location.origin+'/b/'+slug}
$('tenant-slug').addEventListener('input',()=>{tenantSlugTouched=!!$('tenant-slug').value.trim();updateTenantPreview()});
$('tenant-name').addEventListener('input',()=>{if(!tenantSlugTouched)$('tenant-slug').value=slugify($('tenant-name').value);updateTenantPreview()});
updateTenantPreview();
async function showCustomer(id){const box=$('customer-detail');box.classList.remove('hidden');box.innerHTML='<p class="muted">Cargando ficha completa…</p>';try{const d=await api('/api/customers/'+id+'/profile');const c=d.customer;const events=[...d.purchases.map(x=>({date:x.created_at,type:'Compra',detail:x.program_name+' · '+x.branch_name+' · '+x.worker_name})),...d.rewards.map(x=>({date:x.claimed_at||x.unlocked_at,type:x.status==='used'?'Premio reclamado':'Premio ganado',detail:x.program_name+' · '+x.name+(x.branch_name?' · '+x.branch_name:'')}))].sort((a,b)=>new Date(b.date)-new Date(a.date));const cards=d.cards.length?'<div class="card-progress-list">'+d.cards.map(x=>'<article><b>'+(x.progress_emoji||'⭐')+' '+x.program_name+'</b><span>'+x.progress+' de '+x.target_purchases+' compras</span><div class="progress"><i style="width:'+Math.min(100,x.progress/x.target_purchases*100)+'%"></i></div><small>Premio: '+x.reward_name+' · Ciclo '+x.cycle+' · Premios disponibles: '+x.available_rewards+' · '+(ES.states[x.program_status]||ES.escape(x.program_status))+'</small></article>').join('')+'</div>':'<p class="muted">Este cliente todavía no tiene campañas asignadas.</p>';const history=events.length?'<div class="history-list">'+events.map(x=>'<div class="history-item '+(x.type.includes('Premio')?'reward':'')+'"><p><b>'+x.type+'</b></p><p>'+x.detail+'</p><p class="history-date">'+new Date(x.date).toLocaleString('es-CO',{hour12:true})+'</p></div>').join('')+'</div>':'<p class="muted">Todavía no tiene movimientos.</p>';box.innerHTML='<div class="detail-header"><div><p class="eyebrow">FICHA DEL CLIENTE</p><h2>'+c.name+'</h2><p><b>'+c.phone+'</b> · '+(ES.states[c.status]||ES.escape(c.status))+'</p></div><button type="button" class="secondary" onclick="document.getElementById(\'customer-detail\').classList.add(\'hidden\')">Cerrar</button></div><div class="detail-facts"><span><b>Negocio</b>'+c.business_name+'</span><span><b>Sucursal de origen</b>'+(c.origin_branch_name||'No indicada')+(c.origin_branch_city?' · '+c.origin_branch_city:'')+'</span><span><b>Promociones</b>'+(c.marketing_consent?'Autorizadas':'No autorizadas')+'</span><span><b>Registro</b>'+new Date(c.created_at).toLocaleString('es-CO',{hour12:true})+'</span></div><h3>Progreso de fidelización</h3>'+cards+'<h3>Historial completo</h3>'+history}catch(e){box.innerHTML='<p class="error">'+e.message+'</p>'}}
$('customer-search-button').onclick=loadCustomers;$('customer-search-clear').onclick=()=>{$('customer-search').value='';loadCustomers()};$('customer-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();loadCustomers()}};

async function loadTimeBranches(){if(!tenants.length)return;const id=+$('time-tenant').value||tenants[0].id,rows=await api('/api/branches?tenant_id='+id),old=$('time-branch').value;$('time-branch').innerHTML='<option value="">Todas las sucursales</option>'+opts(rows);if([...$('time-branch').options].some(x=>x.value===old))$('time-branch').value=old;await Promise.all([loadTimeServices(),loadTimeSessions()])}
async function loadTimeServices(){const id=+$('time-tenant').value,branch=$('time-branch').value;if(!id)return;try{const rows=await api(`/api/time-services?tenant_id=${id}${branch?'&branch_id='+branch:''}`);$('time-services').innerHTML=rows.length?rows.map(x=>`<div class="tenant"><div><b>⏱️ ${ES.escape(x.name)}</b><small>${x.duration_minutes} min · $${Number(x.price).toLocaleString('es-CO')}${x.branch_id?' · Sucursal específica':' · Todas las sucursales'}</small></div><button type="button" class="${x.status==='active'?'trash':'resume'} mini-action" onclick="setTimeService(${x.id},${x.status!=='active'})">${x.status==='active'?'Desactivar':'Reactivar'}</button></div>`).join(''):'<p class="muted">No hay servicios por tiempo configurados.</p>'}catch(e){$('time-services').innerHTML='<p class="error">'+ES.escape(e.message)+'</p>'}}
async function loadTimeSessions(){const id=+$('time-tenant').value,branch=$('time-branch').value;if(!id)return;try{const rows=await api(`/api/time-sessions?tenant_id=${id}${branch?'&branch_id='+branch:''}`),now=Date.now();$('time-sessions').innerHTML=rows.length?rows.map(x=>{const elapsed=x.status==='open'?Math.max(1,Math.ceil((now-new Date(x.started_at))/60000)):x.minutes_used;return `<div class="tenant"><div><b>${x.status==='open'?'🟢 Abierta':'✓ Cerrada'} · ${ES.escape(x.service_name)}</b><small>${ES.escape(x.customer_name)} · ${ES.escape(x.branch_name)} · ${elapsed} min${x.status==='open'?' en curso':' · $'+Number(x.total_price||0).toLocaleString('es-CO')}</small></div>${x.status==='open'?`<button type="button" class="secondary mini-action" onclick="closeTimeSession(${x.id})">Cerrar</button>`:''}</div>`}).join(''):'<p class="muted">No hay sesiones registradas.</p>'}catch(e){$('time-sessions').innerHTML='<p class="error">'+ES.escape(e.message)+'</p>'}}
async function setTimeService(id,active){try{await api(`/api/time-services/${id}/status`,{method:'PUT',body:JSON.stringify({active})});await loadTimeServices()}catch(e){showToast(e.message,'error')}}
async function closeTimeSession(id){if(!confirm('¿Cerrar esta sesión ahora?'))return;try{const r=await api(`/api/time-sessions/${id}/close`,{method:'POST',body:JSON.stringify({})});showToast(`Sesión cerrada: ${r.minutes_used} minutos.`,'success');await loadTimeSessions()}catch(e){showToast(e.message,'error')}}
$('time-service-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/time-services',{method:'POST',body:JSON.stringify({tenant_id:+$('time-tenant').value,branch_id:+$('time-branch').value||null,name:$('time-service-name').value,duration_minutes:+$('time-duration').value,price:+$('time-price').value})});$('time-message').textContent='Servicio creado. El trabajador ya podrá iniciar sesiones.';e.target.reset();$('time-duration').value=60;$('time-price').value=0;await loadTimeServices()}catch(x){$('time-message').textContent=x.message;showToast(x.message,'error')}};
$('time-tenant').onchange=loadTimeBranches;$('time-branch').onchange=()=>{loadTimeServices();loadTimeSessions()};$('refresh-time-sessions').onclick=loadTimeSessions;document.querySelector('[data-view="time-sales"]').addEventListener('click',()=>{loadTimeBranches()});setInterval(()=>{if(currentMe&&!document.hidden&&!$('view-time-sales').classList.contains('hidden'))loadTimeSessions()},30000);

async function loadSystemUrls(){try{
  const d=await api('/api/system/urls');
  const device=/Android|iPhone|iPad|Mobile/i.test(navigator.userAgent)?'CELULAR':'PC';
  const lines=['ESTE DISPOSITIVO ('+device+')','Administrador: '+d.current.admin,'Trabajador: '+d.current.worker,'','OTRAS DIRECCIONES','PC · Administrador: '+d.pc.admin,'PC · Trabajador: '+d.pc.worker];
  d.mobile.forEach((m,i)=>lines.push('CELULAR '+(i+1)+' · Administrador: '+m.admin,'CELULAR '+(i+1)+' · Trabajador: '+m.worker));
  lines.push('', 'PÁGINAS DE CLIENTES POR NEGOCIO');
  d.businesses.forEach(b=>{lines.push(b.name+' · CLIENTE EN ESTE PC: '+b.current_url,b.name+' · TRABAJADOR EN ESTE PC: '+b.current_worker_url);b.mobile.forEach((m,i)=>lines.push(b.name+' · CLIENTE EN CELULAR '+(i+1)+': '+m.url,b.name+' · TRABAJADOR EN CELULAR '+(i+1)+': '+m.worker_url))});
  if(!d.mobile.length)lines.push('No se detectó la IP Wi-Fi. Conecta el computador y pulsa Actualizar.');
  lastUrlText=lines.join('\n');
  const general=`<div class="url-group current-url"><b>Detectado automáticamente: ${device}</b><code>Administrador: ${d.current.admin}</code><code>Trabajador: ${d.current.worker}</code></div><div class="url-group"><b>Otras direcciones disponibles</b><code>PC · Administrador: ${d.pc.admin}</code><code>PC · Trabajador: ${d.pc.worker}</code>${d.mobile.map((m,i)=>`<code>CELULAR ${i+1} · Administrador: ${m.admin}</code><code>CELULAR ${i+1} · Trabajador: ${m.worker}</code>`).join('')}</div>`;
  const clients=d.businesses.map(b=>`<div class="url-group"><b>🏪 ${b.name}</b><a class="url-access client" href="${b.current_url}" target="_blank">Abrir cliente en este PC</a><a class="url-access worker" href="${b.current_worker_url}" target="_blank">Abrir trabajador en este PC</a>${b.mobile.map((m,i)=>`<code>Cliente celular ${i+1}: ${m.url}</code><code>Trabajador celular ${i+1}: ${m.worker_url}</code>`).join('')}</div>`).join('');
  $('system-urls').innerHTML=general+(clients||'<p class="muted">Todavía no hay negocios activos.</p>')+(d.mobile.length?'':'<p class="muted">No se detectó la IP Wi-Fi. Conecta el computador y pulsa Actualizar.</p>');
}catch(e){$('system-urls').textContent=e.message}}
$('copy-system-urls').onclick=()=>navigator.clipboard.writeText(lastUrlText).then(()=>alert('URL copiadas para PC y celular.'));
