async function exportData(kind){try{const id=+$('customer-tenant').value;await downloadAuthorized('/api/export/'+kind+'?tenant_id='+id,'negrosky_'+kind+'.csv')}catch(e){alert(e.message)}}
async function loadBackups(){try{const rows=await api('/api/backups');$('backup-list').innerHTML=rows.map(x=>'<div class="tenant"><div><b>'+x.filename+'</b><small>'+(x.kind==='zip'?'📦 ZIP completo':'🗄️ Base de datos')+' · '+Math.ceil(x.size/1024)+' KB · '+new Date(x.modified_at).toLocaleString('es-CO',{hour12:true})+'</small></div><div><button class="secondary mini-action" onclick="downloadBackup(\''+x.filename+'\')">Descargar</button><button class="resume mini-action" onclick="restoreBackup(\''+x.filename+'\')">Restaurar</button></div></div>').join('')||'<p class="muted">Todavía no hay respaldos.</p>'}catch(e){$('backup-list').innerHTML='<p class="muted">Los respaldos completos solo están disponibles para el administrador general.</p>'}}
