const originalShowCustomer=showCustomer;showCustomer=async function(id){await originalShowCustomer(id);try{const d=await api('/api/customers/'+id+'/profile');$('customer-detail').insertAdjacentHTML('beforeend','<h3>Notas internas y etiquetas</h3><label>Etiquetas<input id="customer-tags" value="'+(d.customer.tags||'')+'" placeholder="VIP, frecuente, cumpleaños"></label><label>Notas<textarea id="customer-notes" rows="3">'+(d.customer.notes||'')+'</textarea></label><button type="button" onclick="saveCustomerMeta('+id+')">Guardar notas</button>')}catch(e){}};
