function ensureBackupFileInstaller(){const host=$('backup-list');if(!host||$('backup-file-input'))return;host.insertAdjacentHTML('beforebegin','<div class="backup-install"><label for="backup-file-input">Instalar copia desde el computador (.db o .zip)</label><input id="backup-file-input" type="file" accept=".db,.zip,application/zip,application/x-sqlite3,application/octet-stream"><button id="install-backup-file" type="button" class="secondary">Instalar copia seleccionada</button></div>');$('install-backup-file').onclick=async()=>{const file=$('backup-file-input').files?.[0];if(!file){alert('Selecciona primero un archivo .db o .zip');return}if(!/\.(db|zip)$/i.test(file.name)){alert('Solo se permiten copias .db o .zip');return}if(!confirm('¿Instalar esta copia? Se creará un respaldo automático del estado actual.'))return;const reader=new FileReader();reader.onload=async()=>{try{const r=await api('/api/backup-restore-file',{method:'POST',body:JSON.stringify({filename:file.name,data:reader.result})});alert(r.message);localStorage.removeItem('negrosky_token');location.reload()}catch(e){alert(e.message)}};reader.readAsDataURL(file)}}
const systemTab=document.querySelector('[data-view="system"]');systemTab?.addEventListener('click',()=>setTimeout(ensureBackupFileInstaller,0));setTimeout(ensureBackupFileInstaller,500);
$('detect-duplicates').onclick=async()=>{try{const id=+$('customer-tenant').value,rows=await api('/api/customers/duplicates?tenant_id='+id);$('duplicate-results').innerHTML=rows.length?rows.map(x=>'<div class="duplicate-card"><b>Posible duplicado: '+x.names+'</b><p>Celular: '+x.phone+' · IDs: '+x.customer_ids+'</p><button type="button" onclick="mergeDuplicate(\''+x.customer_ids+'\')">Unir clientes</button></div>').join(''):'<p class="notice">No se encontraron clientes duplicados.</p>'}catch(e){alert(e.message)}};
async function mergeDuplicate(ids){const parts=ids.split(',').map(Number);if(parts.length<2)return;const primary=+(prompt('ID del cliente que deseas conservar:',parts[0])||0),duplicate=+(prompt('ID duplicado que será unido:',parts[1])||0);if(!primary||!duplicate)return;if(!confirm('Se creará un respaldo antes de unirlos. ¿Continuar?'))return;try{await api('/api/customers/merge',{method:'POST',body:JSON.stringify({primary_id:primary,duplicate_id:duplicate})});$('duplicate-results').innerHTML='<p class="notice">Clientes unidos correctamente.</p>';await loadCustomers()}catch(e){alert(e.message)}}

async function loadAppointmentBranches(){
  if(!tenants.length)return;
  const tenantId=+$('appointment-tenant').value||tenants.find(x=>x.status==='active')?.id;
  if(!tenantId)return;
  const rows=await api('/api/branches?tenant_id='+tenantId);
  const selected=$('appointment-branch').value;
  $('appointment-branch').innerHTML='<option value="">Todas las sucursales</option>'+opts(rows.filter(x=>x.status==='active'));
  if(rows.some(x=>String(x.id)===selected))$('appointment-branch').value=selected;
  await Promise.all([loadAppointmentServices(),loadAppointments()]);
}
async function loadAppointmentServices(){
  const tenantId=+$('appointment-tenant').value,branchId=$('appointment-branch').value;
  if(!tenantId)return;
  try{const rows=await api(`/api/appointment-services?tenant_id=${tenantId}${branchId?'&branch_id='+branchId:''}`);$('appointment-services').innerHTML=rows.length?rows.map(x=>`<div class="tenant"><div><b>📅 ${x.name}</b><small>${x.duration_minutes} minutos${x.price===null?'':' · $'+Number(x.price).toLocaleString('es-CO',{hour12:true})}${x.branch_id?' · Sucursal específica':' · Todas las sucursales'}</small></div><button type="button" class="${x.status==='active'?'trash':'resume'} mini-action" onclick="setAppointmentService(${x.id},${x.status!=='active'})">${x.status==='active'?'Desactivar':'Reactivar'}</button></div>`).join(''):'<p class="muted">No hay servicios de citas configurados.</p>'}catch(e){$('appointment-services').innerHTML='<p class="error">'+e.message+'</p>'}
}
let calendarCursor=null,calendarSelected=null,calendarRows=[];
function businessCalendarZone(){const tenantId=+$('appointment-tenant').value;return tenants.find(x=>x.id===tenantId)?.timezone||'America/Bogota'}
function currentCalendarMonth(){if(!calendarCursor){const today=ES.dayKey(new Date(),businessCalendarZone());calendarCursor=today.slice(0,7);calendarSelected=today}return calendarCursor}
function renderAppointmentCalendar(){
  const month=currentCalendarMonth(),zone=businessCalendarZone(),[year,number]=month.split('-').map(Number);
  const start=(new Date(Date.UTC(year,number-1,1)).getUTCDay()+6)%7;
  const days=new Date(Date.UTC(year,number,0)).getUTCDate();
  $('calendar-month').textContent=new Intl.DateTimeFormat('es-CO',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(year,number-1,1)));
  const counts={};calendarRows.forEach(x=>{const key=ES.dayKey(x.starts_at,zone);if(key.startsWith(month)){counts[key]??={active:0,cancelled:0};counts[key][x.status==='cancelled'?'cancelled':'active']++}});
  const cells=Array.from({length:start},()=>'<span class="calendar-empty"></span>');
  for(let day=1;day<=days;day++){
    const key=`${month}-${String(day).padStart(2,'0')}`,count=counts[key];
    cells.push(`<button type="button" class="calendar-date ${calendarSelected===key?'selected':''}" data-calendar-date="${key}" aria-label="Ver citas del día ${day}"><b>${day}</b>${count?.active?`<small>${count.active} cita${count.active===1?'':'s'}</small>`:''}${count?.cancelled?`<small class="cancelled-count">${count.cancelled} cancelada${count.cancelled===1?'':'s'}</small>`:''}</button>`);
  }
  $('appointment-calendar').innerHTML='<div class="calendar-weekdays">'+['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(x=>`<b>${x}</b>`).join('')+'</div><div class="calendar-grid">'+cells.join('')+'</div>';
  const date=calendarSelected||`${month}-01`;
  $('calendar-day-title').textContent=new Intl.DateTimeFormat('es-CO',{dateStyle:'full',timeZone:'UTC'}).format(new Date(`${date}T12:00:00Z`));
  const dayRows=calendarRows.filter(x=>ES.dayKey(x.starts_at,zone)===date).sort((a,b)=>a.starts_at.localeCompare(b.starts_at));
  $('calendar-day-agenda').innerHTML=dayRows.length?dayRows.map(x=>{
    const active=['scheduled','confirmed'].includes(x.status);
    const delay=x.delay_minutes?`<p class="delay-warning">Demora aproximada: ${x.delay_minutes} minutos · Fin estimado: ${ES.appointmentTime(x.estimated_end_at,zone)}</p>`:'';
    const reason=x.cancellation_reason?`<p>Motivo de cancelación: ${ES.escape(x.cancellation_reason)}</p>`:'';
    return `<article class="calendar-event ${x.status==='cancelled'?'cancelled':''}"><div class="calendar-event-time">${ES.appointmentTime(x.starts_at,zone)}</div><div><b>${ES.escape(x.customer_name)}</b> <span class="calendar-state">${ES.appointmentStates[x.status]||ES.escape(x.status)}</span><p>${ES.escape(x.service_name)} · ${ES.escape(x.branch_name)}</p><p>Duración aproximada: ${x.duration_minutes||Math.round((new Date(x.ends_at)-new Date(x.starts_at))/60000)} minutos · Teléfono: ${ES.escape(x.customer_phone)}</p>${delay}${reason}${active?ES.delayForm(x.id,x.delay_minutes||0):''}<select aria-label="Cambiar estado de la cita" ${active?'':'disabled'} onchange="setAppointmentStatus(${x.id},this.value)"><option value="">Cambiar estado…</option><option value="confirmed">Confirmar</option><option value="completed">Completada</option><option value="cancelled">Cancelar</option><option value="no_show">No asistió</option></select></div></article>`
  }).join(''):'<p class="muted">No hay citas para este día.</p>';
  $('appointment-list').innerHTML=calendarRows.length?`<table><tr><th>Fecha y hora</th><th>Cliente</th><th>Servicio</th><th>Sucursal</th><th>Estado</th></tr>${calendarRows.map(x=>`<tr><td>${ES.dateTime(x.starts_at,zone)}</td><td>${ES.escape(x.customer_name)}<br><small>${ES.escape(x.customer_phone)}</small></td><td>${ES.escape(x.service_name)}</td><td>${ES.escape(x.branch_name)}</td><td>${ES.appointmentStates[x.status]||ES.escape(x.status)}</td></tr>`).join('')}</table>`:'<p class="muted">Todavía no hay citas registradas este mes.</p>';
}
async function loadAppointments(){
  const tenantId=+$('appointment-tenant').value,branchId=$('appointment-branch').value;
  if(!tenantId)return;
  try{calendarRows=await api(`/api/appointments?tenant_id=${tenantId}&month=${currentCalendarMonth()}${branchId?'&branch_id='+branchId:''}`);renderAppointmentCalendar()}
  catch(e){$('appointment-calendar').innerHTML='<p class="error">'+ES.escape(e.message)+'</p>'; $('calendar-day-agenda').textContent=''}
}
$('appointment-calendar').onclick=event=>{const button=event.target.closest('[data-calendar-date]');if(button){calendarSelected=button.dataset.calendarDate;renderAppointmentCalendar()}};
function navigateCalendar(offset){const [year,month]=currentCalendarMonth().split('-').map(Number);const target=new Date(Date.UTC(year,month-1+offset,1));calendarCursor=`${target.getUTCFullYear()}-${String(target.getUTCMonth()+1).padStart(2,'0')}`;calendarSelected=`${calendarCursor}-01`;loadAppointments()}
$('calendar-prev').onclick=()=>navigateCalendar(-1);$('calendar-next').onclick=()=>navigateCalendar(1);
setInterval(()=>{if(currentMe&&!document.hidden&&!$('view-appointments').classList.contains('hidden'))loadAppointments()},20000);
