async function loadNotifications(){
  if(!tenants.length)return;
  const tenantId=+$('notification-tenant').value||tenants.find(x=>x.status==='active')?.id;
  if(!tenantId)return;
  try{const data=await api('/api/notifications?tenant_id='+tenantId);$('notification-summary').textContent=data.unread?`Tienes ${data.unread} notificación(es) nueva(s).`:'No tienes notificaciones pendientes.';$('notification-list').innerHTML=data.items.length?data.items.map(x=>`<article class="notification-card ${x.read_at?'read':'unread'}"><div><span>${x.event_type==='purchase'?'🛒':x.event_type==='reward'?'🎁':x.event_type==='broadcast'?'📣':'📅'}</span><div><b>${ES.escape(x.title)}</b><p>${ES.escape(x.message)}</p>${x.image_url?`<img class="notification-card-image" src="${ES.escape(x.image_url)}" alt="Imagen de la notificación">`:''}<small>${new Date(x.created_at.replace(' ','T')+'Z').toLocaleString('es-CO',{hour12:true})}${x.branch_name?' · '+ES.escape(x.branch_name):''}</small></div></div></article>`).join(''):'<p class="muted">Las compras, premios y citas aparecerán aquí cuando el módulo esté activado.</p>'}catch(e){$('notification-list').innerHTML='<p class="error">'+e.message+'</p>'}
}
