 async function compressNotificationImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('No se pudo leer la imagen'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(Error('La imagen no es válida'));image.onload=()=>{const maxSide=1600,scale=Math.min(1,maxSide/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);let quality=.86,data=canvas.toDataURL('image/jpeg',quality);while(data.length>1_700_000&&quality>.45){quality-=.08;data=canvas.toDataURL('image/jpeg',quality)}if(data.length>1_800_000)reject(Error('La imagen sigue siendo demasiado grande después de comprimirla'));else resolve(data)};image.src=reader.result};reader.readAsDataURL(file)})}
