const publicModuleKeys=['contact','profile','campaigns','rewards','appointments'];
function initModuleOrders(){const choices=publicModuleKeys.map((_,i)=>`<option value="${i+1}">${i+1}</option>`).join('');for(const key of publicModuleKeys)for(const device of ['mobile','desktop'])$('order-'+key+'-'+device).innerHTML=choices}
function readModuleOrder(device){return [...publicModuleKeys].sort((a,b)=>+$('order-'+a+'-'+device).value-+$('order-'+b+'-'+device).value).join(',')}
function setModuleOrder(device,value){const order=(value||'').split(',').filter(x=>publicModuleKeys.includes(x));const normalized=[...order,...publicModuleKeys.filter(x=>!order.includes(x))];normalized.forEach((key,i)=>$('order-'+key+'-'+device).value=i+1)}
initModuleOrders();
let selectedPreviewModule='contact';
function parseWidths(value,defaults){const out={...defaults};if(value&&typeof value==='object'&&!Array.isArray(value)){for(const [key,n] of Object.entries(value)){if(publicModuleKeys.includes(key)&&Number(n))out[key]=Math.max(25,Math.min(100,+n))}return out}for(const item of String(value||'').split(',')){const [key,n]=item.split(':');if(publicModuleKeys.includes(key)&&Number(n))out[key]=Math.max(25,Math.min(100,+n))}return out}
