function formatPublicHour(value){if(!value)return'';const [hour,minute]=value.split(':').map(Number);return new Intl.DateTimeFormat('es-CO',{hour:'numeric',minute:'2-digit',hour12:true,timeZone:'UTC'}).format(new Date(Date.UTC(2020,0,1,hour,minute)))}
