function activeTenantId055(){
  const moduleTenant=+$('module-tenant')?.value||0;
  const moduleViewOpen=!!$('view-modules')&&!$('view-modules').classList.contains('hidden');
  return (moduleViewOpen&&moduleTenant)||+$('active-tenant')?.value||moduleTenant||0;
}
async function refreshAdminModulePreview055(force=false){
  if(currentMe?.role!=='super_admin')return;
  const tenantId=activeTenantId055();
  if(!tenantId){adminPreviewTenant055=0;adminPreviewModules055=null;adminPreviewLoading055=false;applyFeatureVisibility();return}
  if(!force&&adminPreviewTenant055===tenantId&&adminPreviewModules055){applyFeatureVisibility();return}
  adminPreviewLoading055=true;
  applyFeatureVisibility();
  const request=++adminPreviewRequest055;
  try{
    const state=await api('/api/tenant-modules?tenant_id='+tenantId);
    if(request!==adminPreviewRequest055)return;
    adminPreviewTenant055=tenantId;
    adminPreviewModules055=state.modules||{};
  }catch(e){
    if(request!==adminPreviewRequest055)return;
    adminPreviewTenant055=0;
    adminPreviewModules055=null;
  }finally{
    if(request===adminPreviewRequest055)adminPreviewLoading055=false;
  }
  applyFeatureVisibility();
}
