  async function save(e){e.preventDefault();try{const id=+$('birthday-tenant').value;await api('/api/birthday-settings',{method:'PUT',body:JSON.stringify({tenant_id:id,enabled:$('birthday-enabled').checked,days_before:+$('birthday-days').value||0,monthly_limit:+$('birthday-limit').value||0,promotion:$('birthday-promotion').value.trim()})});$('birthday-message').textContent='Configuración de cumpleaños guardada.';await refresh()}catch(x){$('birthday-message').textContent=x.message}}
  setInterval(()=>{if(currentMe&&(currentMe.role==='super_admin'||currentMe.role==='business_admin')){mount();if($('view-birthdays')&&!$('view-birthdays').classList.contains('hidden'))refresh()}},1000);document.addEventListener('click',e=>{if(e.target.closest('[data-view="birthdays"]')){showAdminView('birthdays');refresh()}});
