// Capa de estabilidad: evita solicitudes GET idénticas repetidas por módulos antiguos.
(function(){const originalApi=api,cache=new Map();api=async function(path,o={}){if(o.method&&o.method!=='GET')return originalApi(path,o);const key=path,now=Date.now(),hit=cache.get(key);if(hit&&now-hit.time<1800)return hit.promise;const promise=originalApi(path,o).catch(e=>{cache.delete(key);throw e});cache.set(key,{time:now,promise});return promise}})();
setTimeout(()=>{const modal=document.getElementById('onboarding-modal');if(!modal)return;const sync=()=>document.body.classList.toggle('onboarding-open',!modal.classList.contains('hidden'));new MutationObserver(sync).observe(modal,{attributes:true,attributeFilter:['class']});sync()},800);
// Estabilidad de interfaz: los módulos con actualización periódica no deben
// volver a pintar el DOM cuando la respuesta no cambió.
(function(){const d=Object.getOwnPropertyDescriptor(Element.prototype,'innerHTML');if(!d||!d.set||window.__stableDomGuard)return;window.__stableDomGuard=true;Object.defineProperty(Element.prototype,'innerHTML',{configurable:d.configurable,enumerable:d.enumerable,get:d.get,set(v){if(d.get.call(this)===v)return;d.set.call(this,v)}})})();
// Las lecturas automáticas usan una ventana de caché más amplia; las acciones
// POST/PUT/DELETE siguen pasando siempre y actualizan los datos al guardar.
(function(){const originalApi=api,cache=new Map();api=async function(path,o={}){if(o.method&&o.method!=='GET')return originalApi(path,o);const key=path,now=Date.now(),hit=cache.get(key);if(hit&&now-hit.time<10000)return hit.promise;const promise=originalApi(path,o).catch(e=>{cache.delete(key);throw e});cache.set(key,{time:now,promise});return promise}})();
